import { Duel } from './js/engine.js';
import { createCard } from './js/cards.js';

const d = new Duel({ deckId: 'flame', oppDeckId: 'abyss', first: 'you' });
d.turn = 'you';
d.hand.you = [createCard('vd11'), createCard('genbu')];
d.field.you.monster = [
  { card: createCard('guardian'), position: 'atk', faceDown: false, atkMod: 0, defMod: 0, attacked: false, summonedTurn: 1, owner: 'you' },
  null, null, null, null,
];
const ev = d.specialSummon('you', d.hand.you[0].uid, 1, { kind: 'monster', idx: 0 });
const vd = d.field.you.monster[1];
console.log('special summon:', vd.card.name, 'releasedDef', vd.releasedDef, 'atkForAttack', d.atkForAttack('you', vd), 'field', d.field.you.monster.filter(Boolean).length);

d.turn = 'opp';
d.field.opp.monster[0] = { card: createCard('dragonia'), position: 'atk', faceDown: false, atkMod: 600, defMod: 0, attacked: false, summonedTurn: 2, owner: 'opp' };
const lpBefore = { ...d.lp };
const ev2 = d.attack('opp', 'monster', 0, { kind: 'monster', idx: 1 });
console.log('battle damage events:', JSON.stringify(ev2.filter(e => e.type === 'damage' || e.type === 'redirect')));
console.log('LP', lpBefore, '->', d.lp, 'vd11 alive', !!d.field.you.monster[1]);
